+ *
+ * @param buf buffer to write formatted string to
+ * @param value value to format
+ *
+ */
+static void phr_format(char *buf, uint32_t value)
+{
+  snprintf(buf, ITEM_LABEL_LENGTH, "0x%x", value);
+}
